CREATE TABLE IF NOT EXISTS tabor_mining_sites(site_id TEXT PRIMARY KEY, name TEXT NOT NULL, location_label TEXT, power_limit_kw REAL CHECK(power_limit_kw>0), commissioning_state TEXT NOT NULL DEFAULT 'planned' CHECK(commissioning_state IN ('planned','installed','verified')));
CREATE TABLE IF NOT EXISTS tabor_mining_racks(rack_id TEXT PRIMARY KEY, site_id TEXT NOT NULL REFERENCES tabor_mining_sites(site_id), power_budget_kw REAL CHECK(power_budget_kw>0), state TEXT NOT NULL DEFAULT 'planned');
CREATE TABLE IF NOT EXISTS tabor_mining_device_assets(device_id TEXT PRIMARY KEY, rack_id TEXT REFERENCES tabor_mining_racks(rack_id), manufacturer TEXT, model TEXT, nameplate_watts REAL CHECK(nameplate_watts>0), expected_ths REAL CHECK(expected_ths>0), state TEXT NOT NULL DEFAULT 'planned', verified_at TEXT);
CREATE TABLE IF NOT EXISTS tabor_mining_device_observations(id TEXT PRIMARY KEY, device_id TEXT NOT NULL REFERENCES tabor_mining_device_assets(device_id), observed_at TEXT NOT NULL, measured_ths REAL CHECK(measured_ths>=0), measured_watts REAL CHECK(measured_watts>=0), temperature_c REAL, source TEXT NOT NULL, receipt TEXT);
